import type {
  InferContractRouterInputs,
  InferContractRouterOutputs,
} from "@orpc/contract";
import type { UIMessage, UIMessageChunk } from "ai";
import { z } from "zod";
import {
  AdmissionLabelSchema,
  stateCodeSchema,
  studentIdSchema,
  unitIdSchema,
} from "../admissions";
import { createContractProcedureBuilder } from "../errors";
import { universityLogoSchema } from "../search";

const CURRENT_YEAR_MIN = 2000;
const CURRENT_YEAR_MAX = 2100;

const onboardingSteps = [
  "personal",
  "graduation",
  "highSchool",
  "academics",
  "tests",
  "preferences",
  "extracurricular",
  "complete",
] as const;

const onboardingStepSchema = z.enum(onboardingSteps);

const nameSchema = z.string().min(1).max(100);

const graduationSchema = z
  .number()
  .int()
  .min(CURRENT_YEAR_MIN)
  .max(CURRENT_YEAR_MAX);

const gpaSchema = z.number().min(0).max(4);

const satSectionSchema = z.number().int().min(200).max(800);
const satTotalSchema = z.number().int().min(400).max(1600);
const actCompositeSchema = z.number().int().min(1).max(36);

const testSelectionSchema = z.enum(["SAT", "ACT", "PSAT", "NONE"]);

// Import from shared to avoid circular dependencies
import { highSchoolSourceSchema } from "../shared/constants";

export {
  type HighSchoolSource,
  highSchoolSourceSchema,
} from "../shared/constants";

const onboardingPersonalSchema = z
  .object({
    firstName: z.string().nullable(),
    lastName: z.string().nullable(),
  })
  .strict();

const onboardingGraduationSchema = z
