const extracurricularCategoryValues = [
  "ACADEMICS",
  "SERVICE",
  "ARTS",
  "SPORTS",
  "WORK",
  "OTHER",
] as const;

const extracurricularRoleLevelValues = [
  "PARTICIPANT",
  "LEADER",
  "FOUNDER",
] as const;

const extracurricularImpactLevelValues = [
  "SCHOOL",
  "REGIONAL",
  "NATIONAL",
  "INTERNATIONAL",
] as const;

type UIMessageWithToolRole = UIMessage & {
  role: UIMessage["role"] | "tool";
};

const uiMessageSchema: z.ZodType<UIMessageWithToolRole> = z
  .object({
    id: z.string().min(1),
    role: z.enum(["system", "user", "assistant", "tool"]),
    parts: z.array(z.unknown()),
    metadata: z.unknown().optional(),
  })
  .strict() as unknown as z.ZodType<UIMessageWithToolRole>;

const extracurricularTranscriptSchema: z.ZodType<UIMessageWithToolRole[]> = z
  .array(uiMessageSchema)
  .max(500) as unknown as z.ZodType<UIMessageWithToolRole[]>;

const extracurricularCategorySchema = z.enum(extracurricularCategoryValues);
const extracurricularRoleLevelSchema = z.enum(extracurricularRoleLevelValues);
const extracurricularImpactLevelSchema = z.enum(
  extracurricularImpactLevelValues,
);

export const extracurricularActivitySchema = z
  .object({
    id: z.string().uuid(),
    title: z.string().min(1).max(320),
    category: extracurricularCategorySchema,
    roleLevel: extracurricularRoleLevelSchema,
    impactLevel: extracurricularImpactLevelSchema,
    hoursPerWeek: z.number().int().min(0).max(200),
    weeksPerYear: z.number().int().min(0).max(52),
    startGrade: z.number().int().min(6).max(12).nullable().optional(),
    endGrade: z.number().int().min(6).max(12).nullable().optional(),
    isPaidOrCaregiving: z.boolean().optional(),
    summary: z.string().min(1).max(1320).nullable().optional(),
  })
  .strict()
  .refine(
    (value) => {
      if (value.startGrade === null || value.startGrade === undefined) {
        return true;
      }
      if (value.endGrade === null || value.endGrade === undefined) {
        return true;
      }
      return value.startGrade <= value.endGrade;
    },
    {
      message: "startGrade must be less than or equal to endGrade",
      path: ["endGrade"],
    },
  );

const onboardingExtracurricularSchema = z
  .object({
    activities: z.array(extracurricularActivitySchema),
    derivedScore01: z.number().min(0).max(1).nullable().optional(),
    acknowledgedNoActivities: z.boolean().optional(),
    transcript: extracurricularTranscriptSchema.optional(),
  })
  .strict()
  .refine(
    (value) => {
      if (value.acknowledgedNoActivities) {
        return value.activities.length === 0;
      }
      return true;
    },
    {
      message:
        "Activities must be empty when acknowledging that there are no activities",
      path: ["activities"],
    },
  );

const onboardingStateSchema = z
  .object({
    currentStep: onboardingStepSchema,
    completedSteps: z.array(onboardingStepSchema),
    personal: onboardingPersonalSchema,
    graduation: onboardingGraduationSchema,
    highSchool: onboardingHighSchoolSchema,
    academics: onboardingAcademicsSchema,
    tests: onboardingTestsSchema.nullable(),
    preferences: onboardingPreferencesSchema.nullable(),
    extracurricular: onboardingExtracurricularSchema.nullable(),
    updatedAt: z.string().nullable(),
  })
  .strict();

const contractProcedure = createContractProcedureBuilder();

const extracurricularInterviewSessionSchema = z
  .object({
    sessionId: z.string().min(1).max(128),
    hasActiveStream: z.boolean(),
    status: z.enum(["idle", "streaming", "completed", "error"]),
    messages: z.array(uiMessageSchema),
  })
  .strict();

const savePersonalInputSchema = z
  .object({
    firstName: nameSchema,
    lastName: nameSchema,
  })
  .strict();

const saveGraduationInputSchema = z
  .object({
    graduationYear: graduationSchema,
  })
  .strict();

const saveHighSchoolInputSchema = z
  .object({
    highSchoolId: z.string().min(1).optional(),
    highSchoolName: z.string().min(1).optional(),
    stateCode: stateCodeSchema.optional(),
  })
  .strict()
  .refine((value) => Boolean(value.highSchoolId || value.highSchoolName), {
    message: "Select a known high school or provide a custom name.",
    path: ["highSchoolName"],
  })
  .refine(
    (value) => {
      if (value.highSchoolId) {
        return true;
      }
      return Boolean(value.stateCode);
    },
    {
      message: "Provide the state for custom high schools.",
      path: ["stateCode"],
    },
  );

const saveAcademicsInputSchema = z
  .object({
    gpaUnweighted4: gpaSchema,
  })
  .strict();

const saveTestsInputSchema = onboardingTestsSchema
  .refine(
    (value) => {
      const selections = value.selections;
      if (selections.includes("NONE") && selections.length > 1) {
        return false;
      }
      if (selections.includes("SAT")) {
        return Boolean(value.sat);
      }
      if (selections.includes("ACT")) {
        return Boolean(value.act);
      }
      if (selections.includes("PSAT")) {
        return Boolean(value.psat);
      }
      return true;
    },
    {
      message: "Provide matching score details for each selected test.",
      path: ["selections"],
    },
  )
  .refine(
    (value) => {
      if (!value.sat) {
        return true;
      }
      const expectedTotal = value.sat.math + value.sat.readingAndWriting;
      return expectedTotal === value.sat.total;
    },
    {
      message: "SAT total must equal Math plus Reading & Writing.",
      path: ["sat", "total"],
    },
  );

const savePreferencesInputSchema = z
